// getBodyFromSeeker returns a GetBody for a body that is an io.Seeker (for
// example an *os.File used for uploads), rewinding it to the position it had
// when this was called. It returns nil if the body cannot be replayed.
func getBodyFromSeeker(body io.Reader) func() (io.ReadCloser, error) {
	seeker, ok := body.(io.Seeker)
	if !ok {
		return nil
	}
	pos, err := seeker.Seek(0, io.SeekCurrent)
	if err != nil {
		return nil
	}
	return func() (io.ReadCloser, error) {
		if _, err := seeker.Seek(pos, io.SeekStart); err != nil {
			return nil, err
		}
		return io.NopCloser(body), nil
	}
}

