func TestRetryTransport_RetriesSeekableBodyOn429(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var bodies [][]byte
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		body, err := io.ReadAll(req.Body)
		if err != nil {
			t.Errorf("read request body: %v", err)
		}
		mu.Lock()
		bodies = append(bodies, body)
		attempt := len(bodies)
		mu.Unlock()

		status := 429
		if attempt == 2 {
			status = 200
		}
		return &http.Response{
			StatusCode: status,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, DefaultRetryPolicy(), retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	path := filepath.Join(t.TempDir(), "upload.bin")
	if err := os.WriteFile(path, []byte("upload-payload"), 0o644); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open temp file: %v", err)
	}
	t.Cleanup(func() { _ = file.Close() })

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", file)
	if req.GetBody != nil {
		t.Fatalf("precondition: expected no GetBody for *os.File body")
	}

	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	mu.Lock()
	defer mu.Unlock()
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	for i, body := range bodies {
		if string(body) != "upload-payload" {
			t.Fatalf("attempt %d body = %q, want full payload", i+1, body)
		}
	}
	if resp.StatusCode != 200 {
		t.Fatalf("expected status 200, got %d", resp.StatusCode)
	}
}

func TestRetryTransport_RetriesSeekablePostOn503WithRetryAllMethods(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		if _, err := io.Copy(io.Discard, req.Body); err != nil {
			t.Errorf("drain request body: %v", err)
		}
		mu.Lock()
		calls++
		mu.Unlock()
		return &http.Response{
			StatusCode: 503,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	policy := DefaultRetryPolicy()
	policy.MaxAttempts = 2
	policy.RetryAllMethods = true
	rt := newRetryTransport(next, policy, retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	path := filepath.Join(t.TempDir(), "upload.bin")
	if err := os.WriteFile(path, []byte("upload-payload"), 0o644); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open temp file: %v", err)
	}
	t.Cleanup(func() { _ = file.Close() })

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", file)
