		// os.Open) so the request gets a working GetBody, letting
		// retries after 429/5xx replay the full body, and a known
		// Content-Length instead of chunked transfer.
		buf, err := io.ReadAll(b)
		if err != nil {
			return fmt.Errorf("read request body: %w", err)
		}
		reqBody = bytes.NewReader(buf)
	default:
		buf, err := json.Marshal(b)
		if err != nil {
			return fmt.Errorf("encode json body: %w", err)
		}
		reqBody = bytes.NewReader(buf)
	}
}

