func TestRawClient_Do_UploadBodyNotReplayableStopsOn429(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var attempts int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.Copy(io.Discard, r.Body)
		mu.Lock()
		attempts++
		mu.Unlock()

		w.Header().Set("Retry-After", "1")
		w.WriteHeader(http.StatusTooManyRequests)
		_, _ = w.Write([]byte(`{"code":"rate_limit","message":"Too many requests"}`))
	}))
	t.Cleanup(srv.Close)

	pipeReader, pipeWriter := io.Pipe()
	go func() {
		_, _ = pipeWriter.Write([]byte("streaming"))
		_ = pipeWriter.Close()
	}()

	policy := RetryPolicy{
		MaxAttempts: 3,
		BaseDelay:   time.Millisecond,
		MaxDelay:    2 * time.Millisecond,
		Jitter:      func(d time.Duration) time.Duration { return d },
	}
	httpClient := NewHTTPClient(Config{
		HTTPClient:  srv.Client(),
		RetryPolicy: &policy,
	})

	raw, err := NewRawClient(srv.URL, httpClient)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	err = raw.Do(context.Background(), http.MethodPost, "/files", nil, pipeReader, nil)
	var rlErr *RateLimitError
	if !errors.As(err, &rlErr) {
		t.Fatalf("expected RateLimitError, got %T (%v)", err, err)
	}

	mu.Lock()
	defer mu.Unlock()
	if attempts != 1 {
		t.Fatalf("expected 1 attempt for non-replayable body, got %d", attempts)
	}
}

