		contentType := r.Header.Get("Content-Type")
		if !strings.HasPrefix(contentType, "multipart/form-data; boundary=") {
			t.Fatalf("unexpected content type: %q", contentType)
		}

		reader := multipart.NewReader(r.Body, strings.TrimPrefix(contentType, "multipart/form-data; boundary="))
		fileName := ""
		var fileContent []byte
		fields := map[string]string{}
		for {
			part, err := reader.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Fatalf("next part: %v", err)
			}
			data, err := io.ReadAll(part)
			if err != nil {
				t.Fatalf("read part: %v", err)
			}
			if part.FileName() != "" {
				if part.FormName() != "file" {
					t.Fatalf("unexpected file field: %q", part.FormName())
				}
				fileName = part.FileName()
				fileContent = data
			} else {
				fields[part.FormName()] = string(data)
			}
			_ = part.Close()
		}
		if fileName != "report.pdf" {
			t.Fatalf("unexpected file name: %q", fileName)
		}
		if string(fileContent) != "pdf-bytes" {
			t.Fatalf("unexpected file content: %q", fileContent)
		}
		if got := fields["deal_id"]; got != "77" {
			t.Fatalf("unexpected deal_id: %q", got)
		}
		if got := fields["lead_id"]; got != "abc-123" {
			t.Fatalf("unexpected lead_id: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":55,"name":"report.pdf"}}`))
	})

	file, err := client.Files.AddFile(
		context.Background(),
		"report.pdf",
		strings.NewReader("pdf-bytes"),
		WithFilesDealID(DealID(77)),
		WithFilesLeadID(LeadID("abc-123")),
