func TestFilesService_AddFile_Retries429(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var attempts int
	var lastFileContent string
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        2 * time.Millisecond,
			RetryAllMethods: true,
			Jitter:          func(d time.Duration) time.Duration { return d },
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		contentType := r.Header.Get("Content-Type")
		if !strings.HasPrefix(contentType, "multipart/form-data; boundary=") {
			t.Errorf("unexpected content type: %q", contentType)
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		reader := multipart.NewReader(r.Body, strings.TrimPrefix(contentType, "multipart/form-data; boundary="))
		for {
			part, err := reader.NextPart()
			if err == io.EOF {
				break
			}
			if err != nil {
				t.Errorf("next part: %v", err)
				break
			}
			if part.FileName() != "" {
				data, err := io.ReadAll(part)
				if err != nil {
					t.Errorf("read part: %v", err)
					break
				}
				mu.Lock()
				lastFileContent = string(data)
				mu.Unlock()
			}
			_ = part.Close()
		}

		mu.Lock()
		attempts++
		current := attempts
		mu.Unlock()

		if current == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":66,"name":"upload.bin"}}`))
	})

	path := filepath.Join(t.TempDir(), "upload.bin")
	if err := os.WriteFile(path, []byte("bulk-import-bytes"), 0o644); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open temp file: %v", err)
	}
	t.Cleanup(func() { _ = file.Close() })

	uploaded, err := client.Files.AddFile(context.Background(), "upload.bin", file)
	if err != nil {
		t.Fatalf("AddFile error: %v", err)
	}
	if uploaded.ID != 66 {
		t.Fatalf("unexpected file: %#v", uploaded)
	}

	mu.Lock()
	defer mu.Unlock()
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
	if lastFileContent != "bulk-import-bytes" {
		t.Fatalf("unexpected file content on retry: %q", lastFileContent)
	}
}

